export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdsList = Object.entries(thresholds).map(([metric, min]) => {
    const evaluation = evaluations.find((e) => e.id === metric);
    const score = evaluation?.score ?? null;
    const passed = score !== null && score >= min;
    return {
      metric,
      min,
      score,
      passed
    };
  });

  const passed = thresholdsList.length === 0 || thresholdsList.every((t) => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdsList.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdsList;
  }

  return report;
}

