function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings: string[] | undefined, validMetricIds: string[]): { thresholds: Record<string, number>; errors?: string[] } {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { thresholds: {} };
  }

  const errors: string[] = [];
  const thresholds: Record<string, number> = {};

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      errors.push(`Malformed threshold: "${thresholdStr}" (expected format: metric=number)`);
      continue;
    }

    const [, metric, value] = match;
    const min = parseFloat(value);

    if (!validMetricIds.includes(metric)) {
      errors.push(`Unknown metric: "${metric}" (valid metrics: ${validMetricIds.join(', ')})`);
      continue;
    }

    if (Number.isNaN(min) || min < 0 || min > 1) {
      errors.push(`Invalid threshold value for "${metric}": ${value} (must be a number between 0 and 1)`);
      continue;
    }

    thresholds[metric] = min;
  }

  if (errors.length > 0) {
    return { thresholds, errors };
  }

  return { thresholds };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const validMetricIds = evaluations.map((e: any) => e.id);
  const { thresholds, errors } = parseThresholds(options.threshold, validMetricIds);

  if (errors && errors.length > 0) {
    errors.forEach((error) => log.error(error));
    process.exit(2);
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && Object.keys(thresholds).length > 0 && !report.passed) {
    process.exit(1);
  }
}

function runRagIndexCommand(options: RagOptions) {
  const payload = (Rag.indexDocuments as unknown as (config: unknown) => any)({
    input: options.input,
    output: options.output,
    chunkSize: options.chunkSize,
    extensions: options.extensions
  });
  log.success('RAG index created.', {
    documentCount: payload.metadata.documentCount,
    entryCount: payload.metadata.entryCount,
    output: options.output ?? 'frai-index.json'
  });
}

function runFinetuneTemplateCommand(options: FinetuneTemplateOptions) {
  const template = Finetune.createGovernanceTemplate();
  const target = options.output ? path.resolve(options.output) : path.resolve(process.cwd(), 'frai-finetune-plan.json');
  fs.writeFileSync(target, JSON.stringify(template, null, 2), 'utf8');
  log.success('Fine-tuning governance template written.', { path: target });
}

function runFinetuneValidateCommand(planPath: string, options: FinetuneValidateOptions) {
  const absolute = path.resolve(planPath);
  assertFileExists(absolute);
  const raw = fs.readFileSync(absolute, 'utf8');
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error(`Invalid JSON: ${(error as Error).message}`);
  }
  const validation = Finetune.validateGovernancePlan(parsed);
  if (!validation.valid) {
    log.error('Fine-tuning governance plan is invalid.');
    validation.errors.forEach((errorItem) => {
      console.error(` - ${errorItem.path}: ${errorItem.message}`);
    });
  } else {
    log.success('Fine-tuning governance plan is valid.');
  }

  if (options.readiness) {
    const readiness = Finetune.calculateReadiness(parsed as Parameters<typeof Finetune.calculateReadiness>[0]);
    log.info('Readiness checkpoint status', readiness);
    console.log(Finetune.summarizeGovernance(parsed as Parameters<typeof Finetune.calculateReadiness>[0]));
  }
}

async function handleCompatibilityOptions(options: GenerateOptions & { listDocs?: boolean; clean?: boolean; exportPdf?: boolean; update?: boolean; setup?: boolean; showConfig?: boolean }) {
  if (options.update) {
    checkForUpdates();
    if (!options.scan && !options.setup && !options.listDocs && !options.clean) {
      return;
    }
  }
  if (options.setup) {
    await runSetupFlow(options.key, options.global);
    return;
  }
  if (options.listDocs) {
    listDocs();
    return;
  }
  if (options.clean) {
    cleanDocs();
    return;
  }
  const exportOnly =
    options.exportPdf &&
    !options.scan &&
    !options.ci &&
    !options.setup &&
    !options.listDocs &&
    !options.clean &&
    !options.update &&
    !options.showConfig &&
    !options.key;
  if (exportOnly) {
    exportDocsAsPdf();
    return;
  }
  const showConfigOnly =
    options.showConfig &&
    !options.scan &&
    !options.ci &&
    !options.setup &&
    !options.listDocs &&
    !options.clean &&
    !options.update &&
    !options.exportPdf &&
    !options.key;
  if (showConfigOnly) {
    showConfigStatus();
    return;
  }
  await runGenerateFlow(options);
}

async function main() {
  const program = new Command();

  program
    .name('frai')
    .description('Responsible AI toolkit for documentation, scanning, evaluation, and governance.')
    .version(pkg.version ?? '0.0.0')
    .option('--scan', 'Run code scanning before documentation generation')
    .option('--ci', 'Run in CI mode (scan + exit if no AI indicators)')
    .option('--setup', 'Shortcut to open API key setup flow')
    .option('--key <apiKey>', 'Provide an OpenAI API key for this invocation', undefined)
    .option('--global', 'Persist provided API key in the global config store', false)
    .option('--list-docs', 'List generated documentation files')
    .option('--clean', 'Remove generated documentation files')
    .option('--export-pdf', 'Export documentation files as PDFs')
    .option('--show-config', 'Display API key configuration status')
    .option('--update', 'Check for new CLI releases')
    .action(async (options) => {
      await handleCompatibilityOptions({
        scan: options.scan,
        ci: options.ci,
        setup: options.setup,
        key: options.key,
        global: options.global,
        listDocs: options.listDocs,
        clean: options.clean,
        exportPdf: options.exportPdf,
        showConfig: options.showConfig,
        update: options.update
      });
    });

  program
    .command('generate')
    .description('Run the interactive documentation workflow.')
    .option('--scan', 'Run code scanning before documentation generation')
    .option('--ci', 'Run in CI mode')
    .option('--key <apiKey>', 'Provide an OpenAI API key for this invocation', undefined)
    .option('--global', 'Persist provided API key in the global config store', false)
    .option('--export-pdf', 'Export generated docs to PDF')
    .option('--show-config', 'Display API key configuration status')
    .action(async (options: GenerateOptions) => {
      await runGenerateFlow(options);
    });

  program
    .command('scan')
    .description('Scan the current codebase for AI/ML artefacts.')
    .option('--ci', 'Run in CI mode')
    .option('--json', 'Print raw JSON results')
    .action((options: { ci?: boolean; json?: boolean }) => {
      runScanCommand({
        ci: Boolean(options.ci),
        json: Boolean(options.json),
        silent: false
      });
    });

  program
    .command('setup')
    .description('Configure the OpenAI API key store.')
    .option('--key <apiKey>', 'Provide an API key to store')
    .option('--global', 'Store the API key globally (instead of local project)')
    .action(async (options: { key?: string; global?: boolean }) => {
      await runSetupFlow(options.key, Boolean(options.global));
    });

  program
    .command('config')
    .description('Display API key configuration status.')
    .action(() => {
      showConfigStatus();
    });

  const docsCommand = program.command('docs').description('Manage generated documentation artefacts.');

  docsCommand
    .command('list')
    .description('List generated documentation files.')
    .action(() => listDocs());

  docsCommand
    .command('clean')
    .description('Remove generated documentation files.')
    .action(() => cleanDocs());

  docsCommand
    .command('export')
    .description('Export documentation to PDF using markdown-pdf.')
    .action(() => exportDocsAsPdf());

  program
    .command('rag')
    .description('Compliance-aware retrieval-augmented generation tooling.')
    .command('index')
    .description('Create a vector index for documents.')
    .option('--input <path>', 'Input file or directory (default: cwd)')
    .option('--output <path>', 'Output vector store JSON (default: frai-index.json)')
    .option('--chunk-size <words>', 'Words per chunk (default: 800)', (value) => Number.parseInt(value, 10))
    .option('--extensions <list>', 'Comma-separated list of allowed file extensions', (value) =>
      value.split(',').map((ext) => ext.trim().toLowerCase())
    )
    .action((options: { input?: string; output?: string; chunkSize?: number; extensions?: string[] }) => {
      runRagIndexCommand({
        input: options.input,
        output: options.output,
        chunkSize: options.chunkSize,
        extensions: options.extensions
      });
    });

  program
    .command('eval')
    .description('Run evaluation metrics on model outputs.')
    .requiredOption('--outputs <file>', 'Path to JSON file containing model outputs')
    .option('--references <file>', 'Path to JSON file containing reference outputs')
    .option('--report <path>', 'Report path (default: frai-eval-report.json)')
    .option('--format <format>', 'Report format (json or markdown)', 'json')
    .option('--threshold <metric=min>', 'Metric threshold in format metric=value (0-1), can be specified multiple times')
    .action((options: EvalOptions) => {
      runEvalCommand(options);
    });

  const finetuneCommand = program.command('finetune').description('Fine-tuning governance utilities.');

  finetuneCommand
    .command('template')
    .description('Generate a governance template JSON file.')
    .option('--output <path>', 'Where to write the template (default: frai-finetune-plan.json)')
    .action((options: FinetuneTemplateOptions) => {
      runFinetuneTemplateCommand(options);
    });

  finetuneCommand
    .command('validate <plan>')
    .description('Validate a fine-tuning governance plan JSON.')
    .option('--readiness', 'Calculate readiness checkpoints after validation', false)
    .action((plan: string, options: FinetuneValidateOptions) => {
      runFinetuneValidateCommand(plan, options);
    });

  program
    .command('gate [args...]')
    .description('Responsible AI Gate for specs: init | check <spec> [--smart] | draft. Delegates to frai-gate.')
    .allowUnknownOption(true)
    .helpOption(false)
    .action(async (args: string[]) => {
      const require = createRequire(import.meta.url);
      let gateCli: string;
      try {
        const gatePkg = require.resolve('frai-gate/package.json');
        gateCli = path.join(path.dirname(gatePkg), 'dist', 'cli.js');
      } catch {
        log.error('frai-gate is not installed. Run: npm install -g frai-gate');
        process.exit(2);
      }
      const { spawnSync } = await import('child_process');
      const result = spawnSync(process.execPath, [gateCli, ...(args ?? [])], { stdio: 'inherit' });
      process.exit(result.status ?? 0);
    });

  program
    .command('update')
    .description('Check for new FRAI CLI releases.')
    .action(() => {
      checkForUpdates();
    });

  try {
    await program.parseAsync(process.argv);
  } catch (error) {
    log.error('CLI execution failed.', {
      error: error instanceof Error ? error.message : String(error)
    });
    process.exit(1);
  }
}

void main();

